      const blink = () => { if (api.mode === 'stopped') return; const cur = el.dataset.f || 'rest'; if (cur === 'rest') { show('blink'); setTimeout(() => { if (el.dataset.f === 'blink') show('rest'); }, 140); } api.blinkT = setTimeout(blink, 2200 + Math.random() * 2800); };
